   for(var row:nativePoints.get(source.identity.scenarioId).entrySet()){check(PcArmyActionPolicy.points(w,row.getKey())==row.getValue(),"source-specific original AP driver "+source.identity.scenarioId+"/"+row.getKey());matches++;}
   check(strategy==w.strategy.randomState&&life==w.life.randomState,"native initial AP no random draws");byte[] before=SaveCodec.encode(w);check(Arrays.equals(before,SaveCodec.encode(SaveCodec.decode(before))),"wholeWorld/armyAP/all RNG save exact");
