  byte[] identityGood=play.extensions.get(PcScenarioIdentity.NAMESPACE);play.dataHash="broken";boolean staleSourceRejected=false;try{PcArmyActionPolicy.points(play,0);}catch(IllegalStateException e){staleSourceRejected=true;}check(staleSourceRejected,"cached budget rejects changed live source identity");play.dataHash=PcScenarioCatalog.all().get(0).identity.sha;check(Arrays.equals(identityGood,play.extensions.get(PcScenarioIdentity.NAMESPACE)),"validation does not rewrite source bytes");
