  World unknown=PcScenarioCatalog.load(PcScenarioCatalog.all().get(0).identity.scenarioId,2,42);unknown.extensions.put(PcArmyActionPolicy.NAMESPACE,new byte[]{1,2,3,4,5});Arrays.fill(unknown.actionPoints,60);byte[] unknownBefore=SaveCodec.encode(unknown);check(!PcArmyActionPolicy.enabled(unknown)&&Arrays.equals(unknownBefore,SaveCodec.encode(SaveCodec.decode(unknownBefore))),"unknown opaque policy bytes preserved without adoption");
  var assignments=PcGovernorPolicy.data(play);int priorArmy=assignments.siteArmies.get(home.id);assignments.siteArmies.put(home.id,-1);PcGovernorPolicy.write(play,assignments);byte[] unknownSite=SaveCodec.encode(play);RuleFailure refusal=play.actionPointFailure(home,20);check(refusal.code.equals("ORIGINAL_ARMY_UNKNOWN"),"unknown captured/source site cannot borrow first army points");check(Arrays.equals(unknownSite,SaveCodec.encode(play)),"unknown army preflight no world/RNG mutation");assignments.siteArmies.put(home.id,priorArmy);PcGovernorPolicy.write(play,assignments);
  World budgets=PcScenarioCatalog.load(PcScenarioCatalog.all().get(0).identity.scenarioId,28,42);check(PcArmyActionPolicy.enabled(budgets),"normal source factory initializes saved original budget");int secondary=PcArmyActionPolicy.points(budgets,6);byte[] editorBefore=SaveCodec.encode(budgets);Editor.Draft draft=budgets.editor.faction(28,255,budgets.campaign.points(28));check(draft.valid(),"normal editor validates explicit original first army AP255");check(Arrays.equals(editorBefore,SaveCodec.encode(budgets)),"editor preview allWorld/RNG pure");check(budgets.editor.apply(draft).ok,"ordinary editor apply");check(PcArmyActionPolicy.points(budgets,5)==255&&PcArmyActionPolicy.points(budgets,6)==secondary,"editor changes first army only");check(!budgets.editor.apply(draft).ok,"editor saved stale/double state refused");PcArmyActionPolicy.debitPrimary(budgets,28,20);check(PcArmyActionPolicy.points(budgets,5)==235&&PcArmyActionPolicy.points(budgets,6)==secondary,"management only debits original first army");World.City delegated=budgets.cities.stream().filter(c->c.owner==28&&c.kind==World.SiteKind.CITY&&!budgets.districts.rulerCity(c.id)).findFirst().orElseThrow();int delegatedArmy=PcArmyActionPolicy.cityArmy(budgets,delegated.id);int expectedBefore=PcArmyActionPolicy.points(budgets,5);World.Result configured=budgets.districts.configure(-1,"预算验收",new int[]{delegated.id},Districts.Policy.DEFENSE,-1,-1,false,false);check(configured.ok,"ordinary engineering delegation compiles on explicit saved original budget");check(PcArmyActionPolicy.points(budgets,5)==expectedBefore-20,"configure uses original first army once");byte[] configuredSave=SaveCodec.encode(budgets);World replay=SaveCodec.decode(configuredSave);check(budgets.nextTurn().ok&&replay.nextTurn().ok,"delegation and AI complete wholeturn with independent budgets");check(Arrays.equals(SaveCodec.encode(budgets),SaveCodec.encode(replay)),"delegated fullturn/reload exact independent army AP/World/all RNG");check(PcArmyActionPolicy.points(budgets,delegatedArmy)>=0,"delegated site original army budget retained");PcArmyActionPolicy.clearOwner(budgets,28);check(PcArmyActionPolicy.points(budgets,5)==0&&PcArmyActionPolicy.points(budgets,6)==0&&budgets.actionPoints[28]==0,"collapse clears every owner army and projection");check(Arrays.equals(SaveCodec.encode(budgets),SaveCodec.encode(SaveCodec.decode(SaveCodec.encode(budgets)))),"edited and cleared independent budget complete-save exact");
  System.out.println("PASS original saved army budget "+checks+" checks/285source-specific armies/16sources/independent scope/cumulative turn/save/RNG/old absence; normal APK integration pending");
